import sys


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n = int(line)
        is_negative = n < 0
        abs_n = abs(n)

        factors = []
        m = abs_n
        d = 2
        while d * d <= m:
            count = 0
            while m % d == 0:
                m //= d
                count += 1
            if count > 0:
                if count > 1:
                    factors.append(f"{d}^{count}")
                else:
                    factors.append(str(d))
            d += 1
        if m > 1:
            factors.append(str(m))

        if is_negative:
            print(f"-1 * {' * '.join(factors)}")
        else:
            print(f"{n} = {' * '.join(factors)}")


if __name__ == "__main__":
    main()
